// Package bech32 implements Bech32 encoding as specified by BIP 173.
package bech32

import (
	"fmt"
	"strings"
)

var charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

var generator = []uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}

func polymod(values []byte) uint32 {
	chk := uint32(1)
	for _, v := range values {
		top := chk >> 25
		chk = (chk & 0x1ffffff) << 5
		chk ^= uint32(v)
		for i := 0; i < 5; i++ {
			if (top>>i)&1 == 1 {
				chk ^= generator[i]
			}
		}
	}
	return chk
}

func hrpExpand(hrp string) []byte {
	hrp = strings.ToLower(hrp)
	out := make([]byte, 0, len(hrp)*2+1)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]>>5)
	}
	out = append(out, 0)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]&0x1f)
	}
	return out
}

func verifyChecksum(hrp string, data []byte) bool {
	return polymod(append(hrpExpand(hrp), data...)) == 1
}

func createChecksum(hrp string, data []byte) []byte {
	values := append(hrpExpand(hrp), data...)
	values = append(values, 0, 0, 0, 0, 0, 0)
	mod := polymod(values) ^ 1
	out := make([]byte, 6)
	for i := 0; i < 6; i++ {
		out[i] = byte((mod >> (5 * (5 - i))) & 0x1f)
	}
	return out
}

// convertBits converts from one bit-width base to another.
// from->to, with optional padding.
func convertBits(data []byte, fromBits, toBits uint8, pad bool) ([]byte, error) {
	var acc uint32
	var bits uint8
	var ret []byte
	maxv := uint32((1 << toBits) - 1)
	for _, v := range data {
		if v>>fromBits != 0 {
			return nil, fmt.Errorf("invalid data: %d", v)
		}
		acc = (acc << fromBits) | uint32(v)
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			ret = append(ret, byte((acc>>bits)&maxv))
		}
	}
	if pad {
		if bits > 0 {
			ret = append(ret, byte((acc<<(toBits-bits))&maxv))
		}
	} else if bits >= fromBits {
		return nil, fmt.Errorf("illegal zero padding")
	} else if ((acc << (toBits - bits)) & maxv) != 0 {
		return nil, fmt.Errorf("non-zero padding")
	}
	return ret, nil
}

// Encode encodes the hrp and raw data bytes to a bech32 string.
func Encode(hrp string, data []byte) (string, error) {
	values, err := convertBits(data, 8, 5, true)
	if err != nil {
		return "", err
	}
	chk := createChecksum(hrp, values)
	values = append(values, chk...)
	var sb strings.Builder
	sb.WriteString(strings.ToLower(hrp))
	sb.WriteByte('1')
	for _, b := range values {
		if int(b) >= len(charset) {
			return "", fmt.Errorf("invalid data value: %d", b)
		}
		sb.WriteByte(charset[b])
	}
	return sb.String(), nil
}

// Decode decodes a bech32 string and returns the hrp and raw bytes.
func Decode(s string) (string, []byte, error) {
	if len(s) < 8 {
		return "", nil, fmt.Errorf("invalid bech32 string length %d", len(s))
	}
	lower := strings.ToLower(s)
	upper := strings.ToUpper(s)
	if s != lower && s != upper {
		return "", nil, fmt.Errorf("mixed case string")
	}
	s = lower
	pos := strings.LastIndexByte(s, '1')
	if pos < 1 || pos+7 > len(s) {
		return "", nil, fmt.Errorf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	hrp := s[:pos]
	for i := 0; i < len(hrp); i++ {
		c := hrp[i]
		if c < 33 || c > 126 {
			return "", nil, fmt.Errorf("invalid hrp character: %q", c)
		}
	}
	data := make([]byte, 0, len(s)-pos-1)
	for i := pos + 1; i < len(s); i++ {
		idx := strings.IndexByte(charset, s[i])
		if idx < 0 {
			return "", nil, fmt.Errorf("invalid data character: %q", s[i])
		}
		data = append(data, byte(idx))
	}
	if !verifyChecksum(hrp, data) {
		return "", nil, fmt.Errorf("invalid checksum")
	}
	out, err := convertBits(data[:len(data)-6], 5, 8, false)
	if err != nil {
		return "", nil, err
	}
	return hrp, out, nil
}
