// blockMix computes out = BlockMix_{Salsa20/8,r}(in); in and out have length 128*r.
func blockMix(in, out []byte) {
	r := len(in) / 128
	// X = last 64-byte block of in
	X := make([]byte, 64)
	copy(X, in[(2*r-1)*64:])
	// For i=0..2r-1: X = Salsa20/8(X xor B_i); Y_i = X
	Y := make([]byte, 128*r)
	T := make([]byte, 64)
	for i := 0; i < 2*r; i++ {
		for j := 0; j < 64; j++ {
			T[j] = X[j] ^ in[i*64+j]
		}
		salsa208(T)
		copy(Y[i*64:], T)
		copy(X, T)
	}
	// Permute: out = Y_0 || Y_2 || ... || Y_{2r-2} || Y_1 || Y_3 || ... || Y_{2r-1}
	for i := 0; i < r; i++ {
		copy(out[i*64:], Y[2*i*64:(2*i+1)*64])
		copy(out[(r+i)*64:], Y[(2*i+1)*64:(2*i+2)*64])
	}
}

// integerify returns the integer encoded by the last 64 bytes of b, as a little-endian value.
func integerify(b []byte) uint64 {
	// Scrypt integerify uses just the first 8 bytes of the last 64-byte block.
	return binary.LittleEndian.Uint64(b[len(b)-64:])
}

func romix(b []byte, N int) {
	r := len(b) / 128
	X := make([]byte, 128*r)
	copy(X, b)
	V := make([]byte, 128*r*N)
	tmp := make([]byte, 128*r)
	for i := 0; i < N; i++ {
		copy(V[i*128*r:], X)
		blockMix(X, tmp)
		X, tmp = tmp, X
	}
	for i := 0; i < N; i++ {
		j := int(integerify(X) % uint64(N))
		for k := 0; k < 128*r; k++ {
			X[k] ^= V[j*128*r+k]
		}
		blockMix(X, tmp)
		X, tmp = tmp, X
	}
	copy(b, X)
}

// Key derives a key from the password, salt, and cost parameters, returning a
// byte slice of length keyLen.
// N must be a power of two greater than 1. r and p must satisfy r*p < 2^30.
func Key(password, salt []byte, N, r, p, keyLen int) ([]byte, error) {
	if N <= 1 || N&(N-1) != 0 {
		return nil, errors.New("scrypt: N must be > 1 and a power of 2")
	}
	if uint64(r)*uint64(p) >= 1<<30 {
		return nil, errors.New("scrypt: parameters are too large")
	}

	B := pbkdf2Sha256(password, salt, 1, p*128*r)
	for i := 0; i < p; i++ {
		romix(B[i*128*r:(i+1)*128*r], N)
	}
	return pbkdf2Sha256(password, B, 1, keyLen), nil
}
