		return nil, nil, nil, fmt.Errorf("parsing age header: unexpected intro: %q", firstLine)
	}

	h := &Header{}
	var hdrBuf bytes.Buffer
	hdrBuf.WriteString(headerIntro)
	hdrBuf.WriteByte('\n')

