			if err != nil {
				return nil, nil, nil, fmt.Errorf("parsing age header: invalid MAC: %w", err)
			}
			h.MAC = mac
			hdrBuf.WriteString("---")
			return h, hdrBuf.Bytes(), br, nil
		}
