	if s == "" {
		return errors.New("empty stanza type")
	}
	for _, c := range s {
		if c < 33 || c > 126 {
			return fmt.Errorf("invalid character in stanza type: %q", c)
		}
	}
	return nil
}

func validateStanzaArg(s string) error {
	for _, c := range s {
		if c < 33 || c > 126 {
			return fmt.Errorf("invalid character in stanza argument: %q", c)
		}
	}
	return nil
}

