// header bytes up to and including "---" (for MAC computation) as a separate
// slice.
func writeHeader(w io.Writer, recipients []*Stanza, mac []byte) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString(headerIntro)
	buf.WriteByte('\n')
	for _, s := range recipients {
		buf.WriteString("-> ")
		buf.WriteString(s.Type)
		for _, a := range s.Args {
			buf.WriteByte(' ')
			buf.WriteString(a)
		}
		buf.WriteByte('\n')
		bodyEncoded := b64.EncodeToString(s.Body)
		// Wrap at 64 columns. If length is a multiple of 64, add an empty line.
		for i := 0; i < len(bodyEncoded); i += 64 {
			end := i + 64
			if end > len(bodyEncoded) {
				end = len(bodyEncoded)
			}
			buf.WriteString(bodyEncoded[i:end])
			buf.WriteByte('\n')
		}
		if len(bodyEncoded)%64 == 0 {
			buf.WriteByte('\n')
		}
	}
	buf.WriteString("---")
	if mac == nil {
		// Caller wants header for MAC computation; don't write.
		return buf.Bytes(), nil
	}
	// Otherwise include the MAC
	headerForMac := make([]byte, buf.Len())
	copy(headerForMac, buf.Bytes())
	buf.WriteByte(' ')
	buf.WriteString(b64.EncodeToString(mac))
	buf.WriteByte('\n')
	if _, err := w.Write(buf.Bytes()); err != nil {
		return nil, err
	}
	return headerForMac, nil
}

// marshalStanza formats a stanza to bytes (for external use).
func marshalStanza(s *Stanza) []byte {
	var buf bytes.Buffer
	buf.WriteString("-> ")
	buf.WriteString(s.Type)
	for _, a := range s.Args {
		buf.WriteByte(' ')
		buf.WriteString(a)
	}
	buf.WriteByte('\n')
	bodyEncoded := b64.EncodeToString(s.Body)
	for i := 0; i < len(bodyEncoded); i += 64 {
		end := i + 64
		if end > len(bodyEncoded) {
			end = len(bodyEncoded)
		}
		buf.WriteString(bodyEncoded[i:end])
		buf.WriteByte('\n')
	}
	if len(bodyEncoded)%64 == 0 {
		buf.WriteByte('\n')
	}
	return buf.Bytes()
}
