package age

import (
	"crypto/cipher"
	"errors"
	"io"

	"age-reimpl/internal/chacha20poly1305"
)

const chunkSize = 64 * 1024

type streamReader struct {
	aead       cipher.AEAD
	src        io.Reader
	buf        []byte
	nonce      [12]byte
	out        []byte
	err        error
	done       bool
	eof        bool
}

func newStreamReader(key []byte, src io.Reader) (*streamReader, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	return &streamReader{
		aead: aead,
		src:  src,
		buf:  make([]byte, chunkSize+aead.Overhead()),
	}, nil
}

// incrementNonce increments bytes 0..10 of nonce (big-endian 11-byte counter).
func incrementNonce(nonce *[12]byte) error {
	for i := 10; i >= 0; i-- {
		nonce[i]++
		if nonce[i] != 0 {
			return nil
		}
	}
	return errors.New("chunk counter overflow")
}

func (r *streamReader) Read(p []byte) (int, error) {
	if r.err != nil {
		return 0, r.err
	}
	if len(r.out) == 0 {
		if r.done {
			r.err = io.EOF
			return 0, r.err
		}
		// Read the next chunk.
		n, err := io.ReadFull(r.src, r.buf)
		last := false
		if err == io.EOF {
			// No data; error - we expected at least one chunk always, or that last
			// chunk is signaled by short read.
			// If eof was signaled by previous last byte, it's ok.
			if !r.eof {
				r.err = errors.New("unexpected EOF in CHAR chunks")
				return 0, r.err
			}
			r.err = io.EOF
			return 0, r.err
		}
		if err == io.ErrUnexpectedEOF {
			last = true
		} else if err != nil {
			r.err = err
			return 0, err
		}
		chunk := r.buf[:n]
		if !last {
			// Try to detect end by peeking one byte; if zero, it's the last.
			var b [1]byte
			rn, rerr := r.src.Read(b[:])
			if rerr != nil && rerr != io.EOF {
				r.err = rerr
				return 0, rerr
			}
			if rn == 0 {
				last = true
			} else {
				// Prepend b to src.
				r.src = &singleByteReader{b: b[0], r: r.src}
			}
		}
		if last {
			r.nonce[11] = 1
		}
		plaintext, err := r.aead.Open(nil, r.nonce[:], chunk, nil)
		if err != nil {
			r.err = errors.New("failed to decrypt and authenticate payload chunk")
			return 0, r.err
		}
		if last && len(plaintext) == 0 && r.nonceIsZero() {
			// Single empty last chunk with counter 0 is invalid.
		}
		r.out = plaintext
		if last {
			r.done = true
			r.eof = true
		} else {
			if err := incrementNonce(&r.nonce); err != nil {
				r.err = err
				return 0, err
			}
		}
	}
	n := copy(p, r.out)
	r.out = r.out[n:]
	return n, nil
}

func (r *streamReader) nonceIsZero() bool {
	for i := 0; i < 11; i++ {
		if r.nonce[i] != 0 {
			return false
		}
	}
	return true
}

type singleByteReader struct {
	b    byte
	used bool
	r    io.Reader
}

func (s *singleByteReader) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	if !s.used {
		p[0] = s.b
		s.used = true
		return 1, nil
	}
	return s.r.Read(p)
}

type streamWriter struct {
	aead  cipher.AEAD
	dst   io.Writer
	buf   []byte
	nonce [12]byte
	err   error
}

func newStreamWriter(key []byte, dst io.Writer) (*streamWriter, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	return &streamWriter{
		aead: aead,
		dst:  dst,
		buf:  make([]byte, 0, chunkSize),
	}, nil
}

func (w *streamWriter) Write(p []byte) (int, error) {
	if w.err != nil {
		return 0, w.err
	}
	total := 0
	for len(p) > 0 {
		avail := chunkSize - len(w.buf)
		n := len(p)
		if n > avail {
			n = avail
		}
		w.buf = append(w.buf, p[:n]...)
		p = p[n:]
		total += n
		if len(w.buf) == chunkSize && len(p) > 0 {
			if err := w.flushChunk(false); err != nil {
				w.err = err
				return total, err
			}
		}
	}
	return total, nil
}

func (w *streamWriter) flushChunk(last bool) error {
	if last {
		w.nonce[11] = 1
	}
	ct := w.aead.Seal(nil, w.nonce[:], w.buf, nil)
	if _, err := w.dst.Write(ct); err != nil {
		return err
	}
	w.buf = w.buf[:0]
	if !last {
		if err := incrementNonce(&w.nonce); err != nil {
			return err
		}
	}
	return nil
}

func (w *streamWriter) Close() error {
	if w.err != nil {
		return w.err
	}
	return w.flushChunk(true)
}
