	if w.err != nil {
		return 0, w.err
	}
	total := 0
	for len(p) > 0 {
		avail := chunkSize - len(w.buf)
		n := len(p)
		if n > avail {
			n = avail
		}
		w.buf = append(w.buf, p[:n]...)
		p = p[n:]
		total += n
		if len(w.buf) == chunkSize && len(p) > 0 {
			if err := w.flushChunk(false); err != nil {
				w.err = err
				return total, err
			}
		}
	}
	return total, nil
}

