	wrapKey := make([]byte, 32)
	if _, err := h.Read(wrapKey); err != nil {
		return nil, err
	}
	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize())
	body := aead.Seal(nil, nonce, fileKey, nil)
	args := []string{b64.EncodeToString(ephemeral.PublicKey().Bytes())}
	return []*Stanza{{Type: "X25519", Args: args, Body: body}}, nil
}

func (i *X25519Identity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	for _, s := range stanzas {
		if s.Type != "X25519" {
			continue
		}
		if len(s.Args) != 1 {
			return nil, errors.New("invalid X25519 recipient block")
		}
		share, err := b64.DecodeString(s.Args[0])
		if err != nil {
			return nil, fmt.Errorf("invalid X25519 recipient block: %w", err)
		}
		if len(share) != 32 {
			return nil, errors.New("invalid X25519 recipient block: wrong share length")
		}
		ephPub, err := ecdh.X25519().NewPublicKey(share)
		if err != nil {
			return nil, fmt.Errorf("invalid X25519 recipient block: %w", err)
		}
		shared, err := i.priv.ECDH(ephPub)
		if err != nil {
			return nil, fmt.Errorf("invalid X25519 recipient block: %w", err)
		}
		if isAllZero(shared) {
			return nil, errors.New("invalid X25519 recipient block: shared secret is zero")
		}
		salt := append([]byte{}, share...)
		salt = append(salt, i.priv.PublicKey().Bytes()...)
		h := hkdf.New(sha256.New, shared, salt, []byte(x25519Label))
		wrapKey := make([]byte, 32)
		if _, err := h.Read(wrapKey); err != nil {
			return nil, err
		}
		aead, err := chacha20poly1305.New(wrapKey)
		if err != nil {
			return nil, err
		}
		nonce := make([]byte, aead.NonceSize())
		fk, err := aead.Open(nil, nonce, s.Body, nil)
		if err != nil {
			// Keep going - maybe another stanza matches this identity.
			continue
		}
		if len(fk) != 16 {
			return nil, errors.New("invalid X25519 recipient block: wrong file key length")
		}
		return fk, nil
	}
	return nil, ErrNoIdentityMatch
}

func isAllZero(b []byte) bool {
	var v byte
	for _, c := range b {
		v |= c
	}
	return v == 0
}

// -------- scrypt passphrase --------

const scryptLabel = "age-encryption.org/v1/scrypt"

type ScryptRecipient struct {
	password  []byte
	workFactor int
}

func NewScryptRecipient(password string) *ScryptRecipient {
	return &ScryptRecipient{password: []byte(password), workFactor: 18}
}

// SetWorkFactor sets the log2 work factor. Default is 18.
func (s *ScryptRecipient) SetWorkFactor(wf int) { s.workFactor = wf }

func (s *ScryptRecipient) Wrap(fileKey []byte) ([]*Stanza, error) {
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		return nil, err
	}
	label := append([]byte(scryptLabel), salt...)
	N := 1 << s.workFactor
	key, err := scrypt.Key(s.password, label, N, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize())
	body := aead.Seal(nil, nonce, fileKey, nil)
	args := []string{b64.EncodeToString(salt), strconv.Itoa(s.workFactor)}
	return []*Stanza{{Type: "scrypt", Args: args, Body: body}}, nil
}

type ScryptIdentity struct {
	password []byte
	// maxWorkFactor is the highest log2 work factor to accept. Default 22.
	maxWorkFactor int
}

func NewScryptIdentity(password string) *ScryptIdentity {
	return &ScryptIdentity{password: []byte(password), maxWorkFactor: 22}
}

func (s *ScryptIdentity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	// scrypt must be the only stanza.
	if len(stanzas) != 1 {
		return nil, errors.New("file has scrypt recipient stanza but other recipients; refusing to decrypt")
	}
	st := stanzas[0]
	if st.Type != "scrypt" {
		return nil, ErrNoIdentityMatch
	}
	if len(st.Args) != 2 {
		return nil, errors.New("scrypt recipient stanza with wrong number of arguments")
	}
	salt, err := b64.DecodeString(st.Args[0])
	if err != nil {
		return nil, fmt.Errorf("invalid scrypt salt: %w", err)
	}
	if len(salt) != 16 {
		return nil, errors.New("invalid scrypt salt length")
	}
	wf, err := strconv.Atoi(st.Args[1])
	if err != nil {
		return nil, fmt.Errorf("invalid scrypt work factor: %w", err)
	}
	if strconv.Itoa(wf) != st.Args[1] {
		return nil, errors.New("invalid scrypt work factor encoding")
	}
	if wf > s.maxWorkFactor {
		return nil, fmt.Errorf("scrypt work factor too high: %d", wf)
	}
	if wf <= 0 {
		return nil, fmt.Errorf("invalid scrypt work factor: %d", wf)
	}
	label := append([]byte(scryptLabel), salt...)
	N := 1 << wf
	key, err := scrypt.Key(s.password, label, N, 8, 1, 32)
	if err != nil {
		return nil, err
	}
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, aead.NonceSize())
	fk, err := aead.Open(nil, nonce, st.Body, nil)
	if err != nil {
		return nil, errors.New("incorrect passphrase")
	}
	if len(fk) != 16 {
		return nil, errors.New("invalid file key length")
	}
	return fk, nil
}

// -------- MAC / header auth --------

// headerMAC returns the HMAC-SHA256 of headerData using the MAC key derived from
// fileKey via HKDF-SHA256 with info "header" and no salt.
func headerMAC(fileKey, headerData []byte) []byte {
	h := hkdf.New(sha256.New, fileKey, nil, []byte("header"))
	macKey := make([]byte, 32)
	if _, err := h.Read(macKey); err != nil {
		panic(err)
	}
	m := hmac.New(sha256.New, macKey)
	m.Write(headerData)
	return m.Sum(nil)
}

func verifyMAC(fileKey, headerData, mac []byte) bool {
	expected := headerMAC(fileKey, headerData)
	return subtle.ConstantTimeCompare(expected, mac) == 1
}
