package age

import (
	"crypto/rand"
	"crypto/sha256"
	"errors"
	"fmt"
	"io"

	"age-reimpl/internal/hkdf"
)

// Encrypt encrypts the plaintext read from src to dst, for the given recipients.
// The returned WriteCloser must be closed to flush the last chunk.
func Encrypt(dst io.Writer, recipients ...Recipient) (io.WriteCloser, error) {
	if len(recipients) == 0 {
		return nil, errors.New("no recipients specified")
	}

	// Check if scrypt is mixed with others; if so, error.
	scryptPresent := false
	for _, r := range recipients {
		if _, ok := r.(*ScryptRecipient); ok {
			scryptPresent = true
		}
	}
	if scryptPresent && len(recipients) > 1 {
		return nil, errors.New("an scrypt recipient must be the only one")
	}

	fileKey := make([]byte, 16)
	if _, err := rand.Read(fileKey); err != nil {
		return nil, err
	}

	var stanzas []*Stanza
	for _, r := range recipients {
		s, err := r.Wrap(fileKey)
		if err != nil {
			return nil, err
		}
		stanzas = append(stanzas, s...)
	}

	// Compute header without MAC.
	headerNoMAC, err := writeHeader(nil, stanzas, nil)
	if err != nil {
		return nil, err
	}
	mac := headerMAC(fileKey, headerNoMAC)
	if _, err := writeHeader(dst, stanzas, mac); err != nil {
		return nil, err
	}

	// Generate 16-byte payload nonce.
	nonce := make([]byte, 16)
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	if _, err := dst.Write(nonce); err != nil {
		return nil, err
	}

	// Derive payload key.
	payloadKey := make([]byte, 32)
	h := hkdf.New(sha256.New, fileKey, nonce, []byte("payload"))
	if _, err := h.Read(payloadKey); err != nil {
		return nil, err
	}

	return newStreamWriter(payloadKey, dst)
}

// Decrypt reads and decrypts the data from src using the given identities.
// On success, it returns an io.Reader that provides the plaintext.
func Decrypt(src io.Reader, identities ...Identity) (io.Reader, error) {
	if len(identities) == 0 {
		return nil, errors.New("no identities specified")
	}
	h, hdrBytes, br, err := readHeader(src)
	if err != nil {
		return nil, fmt.Errorf("failed to read header: %w", err)
	}
	// Try each identity.
	var fileKey []byte
	var lastErr error
	for _, id := range identities {
		fk, err := id.Unwrap(h.Recipients)
		if err == nil {
			fileKey = fk
			break
		}
		if !errors.Is(err, ErrNoIdentityMatch) {
			lastErr = err
		}
	}
	if fileKey == nil {
		if lastErr != nil {
			return nil, lastErr
		}
		return nil, errors.New("no identity matched any of the recipients")
	}

	if !verifyMAC(fileKey, hdrBytes, h.MAC) {
		return nil, errors.New("bad header MAC")
	}

	nonce := make([]byte, 16)
	if _, err := io.ReadFull(br, nonce); err != nil {
		return nil, fmt.Errorf("failed to read nonce: %w", err)
	}

	payloadKey := make([]byte, 32)
	hk := hkdf.New(sha256.New, fileKey, nonce, []byte("payload"))
	if _, err := hk.Read(payloadKey); err != nil {
		return nil, err
	}

	return newStreamReader(payloadKey, br)
}
