// Package armor provides an io.Writer and io.Reader that transparently apply
// ASCII-armored PEM encoding of type "AGE ENCRYPTED FILE" to age files.
package armor

import (
	"bufio"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"strings"
)

const (
	beginMark = "-----BEGIN AGE ENCRYPTED FILE-----"
	endMark   = "-----END AGE ENCRYPTED FILE-----"
	lineLen   = 64
)

// NewWriter returns a WriteCloser that writes armored (PEM) data to w.
// Close must be called to emit the final partial line and the end marker.
func NewWriter(w io.Writer) io.WriteCloser {
	return &writer{w: w}
}

type writer struct {
	w          io.Writer
	written    bool
	lineRem    int
	partialBuf []byte // up to 2 bytes
	closed     bool
	enc        *base64.Encoding
}

func (aw *writer) writeHeader() error {
	if aw.written {
		return nil
	}
	aw.written = true
	aw.enc = base64.StdEncoding
	aw.lineRem = lineLen
	if _, err := io.WriteString(aw.w, beginMark+"\n"); err != nil {
		return err
	}
	return nil
}

func (aw *writer) Write(p []byte) (int, error) {
	if err := aw.writeHeader(); err != nil {
		return 0, err
	}
	total := len(p)
	// Join with any partial buffer.
	buf := append(aw.partialBuf, p...)
	// Encode full 3-byte groups.
	n := (len(buf) / 3) * 3
	encoded := make([]byte, aw.enc.EncodedLen(n))
	aw.enc.Encode(encoded, buf[:n])
	aw.partialBuf = append(aw.partialBuf[:0], buf[n:]...)

	// Write encoded bytes wrapped at lineLen columns.
	for len(encoded) > 0 {
		take := aw.lineRem
		if take > len(encoded) {
			take = len(encoded)
		}
		if _, err := aw.w.Write(encoded[:take]); err != nil {
			return 0, err
		}
		encoded = encoded[take:]
		aw.lineRem -= take
		if aw.lineRem == 0 {
			if _, err := io.WriteString(aw.w, "\n"); err != nil {
				return 0, err
			}
			aw.lineRem = lineLen
		}
	}
	return total, nil
}

func (aw *writer) Close() error {
	if aw.closed {
		return nil
	}
	aw.closed = true
	if err := aw.writeHeader(); err != nil {
		return err
	}
	// Flush any partial buffer.
	if len(aw.partialBuf) > 0 {
		encoded := make([]byte, aw.enc.EncodedLen(len(aw.partialBuf)))
		aw.enc.Encode(encoded, aw.partialBuf)
		aw.partialBuf = nil
		// Write encoded bytes wrapped.
		for len(encoded) > 0 {
			take := aw.lineRem
			if take > len(encoded) {
				take = len(encoded)
			}
			if _, err := aw.w.Write(encoded[:take]); err != nil {
				return err
			}
			encoded = encoded[take:]
			aw.lineRem -= take
			if aw.lineRem == 0 {
				if _, err := io.WriteString(aw.w, "\n"); err != nil {
					return err
				}
				aw.lineRem = lineLen
			}
		}
	}
	if aw.lineRem < lineLen {
		if _, err := io.WriteString(aw.w, "\n"); err != nil {
			return err
		}
	}
	_, err := io.WriteString(aw.w, endMark+"\n")
	return err
}

// NewReader returns a reader that transparently decodes ASCII-armored data if present,
// or returns the data unchanged otherwise.
func NewReader(r io.Reader) io.Reader {
	br := bufio.NewReader(r)
	// Peek first non-empty byte to detect armor.
	// We need to sniff to see if the input starts with "-----BEGIN".
	header, err := br.Peek(len(beginMark))
	if err != nil || string(header) != beginMark {
		// Not armored; return as-is but wrap with our bufio.
		return br
	}
	return &reader{br: br, enc: base64.StdEncoding}
}

type reader struct {
	br      *bufio.Reader
	enc     *base64.Encoding
	started bool
	done    bool
	buf     []byte
	err     error
}

func (r *reader) Read(p []byte) (int, error) {
	if r.err != nil {
		return 0, r.err
	}
	if !r.started {
		// Consume BEGIN line.
		line, err := r.br.ReadString('\n')
		if err != nil {
			r.err = err
			return 0, err
		}
		line = strings.TrimRight(line, "\r\n")
		if line != beginMark {
			r.err = fmt.Errorf("armor: expected BEGIN, got %q", line)
			return 0, r.err
		}
		r.started = true
	}
	for len(r.buf) == 0 && !r.done {
		line, err := r.br.ReadString('\n')
		if err != nil && err != io.EOF {
			r.err = err
			return 0, err
		}
		eof := err == io.EOF
		line = strings.TrimRight(line, "\r\n")
		if line == endMark {
			r.done = true
			break
		}
		if line == "" && eof {
			r.err = errors.New("armor: truncated input, no END marker")
			return 0, r.err
		}
		if len(line) > lineLen {
			r.err = fmt.Errorf("armor: line too long")
			return 0, r.err
		}
		// Decode
		decoded, err := r.enc.DecodeString(line)
		if err != nil {
			// Try raw (no padding)
			decoded, err = base64.RawStdEncoding.DecodeString(line)
			if err != nil {
				r.err = fmt.Errorf("armor: invalid base64: %w", err)
				return 0, r.err
			}
		}
		r.buf = append(r.buf, decoded...)
		if eof {
			r.err = errors.New("armor: truncated input, no END marker")
			return 0, r.err
		}
	}
	if len(r.buf) == 0 {
		r.err = io.EOF
		return 0, r.err
	}
	n := copy(p, r.buf)
	r.buf = r.buf[n:]
	return n, nil
}
EOF
