	var identities []age.Identity
	var haveIdentities bool
	for _, p := range iFlags {
		ids, err := parseIdentitiesFile(p, inputIsStdin)
		if err != nil {
			errorf("%s", err.Error())
		}
		identities = append(identities, ids...)
		haveIdentities = true
	}

