func parseRecipient(s string) (age.Recipient, error) {
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "age1") {
		return age.ParseX25519Recipient(s)
	}
	if strings.HasPrefix(s, "ssh-rsa ") || strings.HasPrefix(s, "ssh-ed25519 ") || strings.HasPrefix(s, "sk-ssh-ed25519@openssh.com ") {
		return nil, fmt.Errorf("malformed SSH recipient: %q: ssh: no key found", s)
	}
	if strings.HasPrefix(s, "ssh-") {
		return nil, fmt.Errorf("malformed SSH recipient: %q: ssh: no key found", s)
	}
	return nil, fmt.Errorf("unknown recipient type: %q", s)
