read recipients from standard input.

Identity files contain one or more secret keys ("AGE-SECRET-KEY-1..."),
one per line, or an SSH key. Empty lines and lines starting with "#" are
ignored as comments. Passphrase encrypted age files can be used as
identity files. Multiple key files can be provided, and any unused ones
will be ignored. "-" may be used to read identities from standard input.

When --encrypt is specified explicitly, -i can also be used to encrypt to an
identity file symmetrically, instead or in addition to normal recipients.

Example:
    $ age-keygen -o key.txt
    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p
    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p > data.tar.gz.age
    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age
`

// multiString is a flag.Value for repeated string flags.
type multiString []string

func (m *multiString) String() string       { return strings.Join(*m, ",") }
func (m *multiString) Set(s string) error   { *m = append(*m, s); return nil }

// helpFlag is a boolean-like flag that causes --help to print usage and exit 0.
type helpFlag struct{}

func (helpFlag) String() string { return "false" }
func (helpFlag) IsBoolFlag() bool { return true }
func (h helpFlag) Set(string) error {
	printUsage()
	os.Exit(0)
	return nil
}

func printUsage() {
	fmt.Fprint(os.Stderr, usage)
}

func errorf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "age: error: "+format+"\n", args...)
	fmt.Fprintln(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report")
	os.Exit(1)
}

func errorWithHint(hint, format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "age: error: "+format+"\n", args...)
	fmt.Fprintln(os.Stderr, "age: hint: "+hint)
	fmt.Fprintln(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report")
	os.Exit(1)
}

func warningf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "age: warning: "+format+"\n", args...)
}

// version returns the version string embedded in the binary (or a default).
func versionStr() string {
	info, ok := debug.ReadBuildInfo()
	if !ok || info.Main.Version == "" || info.Main.Version == "(devel)" {
		return "v0.0.0-20260414014000-96fce988442d"
	}
	return info.Main.Version
}

func main() {
	fs := flag.NewFlagSet("age", flag.ExitOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = printUsage

	var (
		encryptFlag        bool
		decryptFlag        bool
		passphraseFlag     bool
		armorFlag          bool
		versionFlag        bool
		outputPath         string
		recipientsList     multiString
		recipientsFiles    multiString
		identitiesList     multiString
		pluginList         multiString
	)

	fs.BoolVar(&encryptFlag, "e", false, "")
	fs.BoolVar(&encryptFlag, "encrypt", false, "")
	fs.BoolVar(&decryptFlag, "d", false, "")
	fs.BoolVar(&decryptFlag, "decrypt", false, "")
	fs.BoolVar(&passphraseFlag, "p", false, "")
	fs.BoolVar(&passphraseFlag, "passphrase", false, "")
	fs.BoolVar(&armorFlag, "a", false, "")
	fs.BoolVar(&armorFlag, "armor", false, "")
	fs.BoolVar(&versionFlag, "version", false, "")
	fs.StringVar(&outputPath, "o", "", "")
	fs.StringVar(&outputPath, "output", "", "")
	fs.Var(&recipientsList, "r", "")
	fs.Var(&recipientsList, "recipient", "")
	fs.Var(&recipientsFiles, "R", "")
	fs.Var(&recipientsFiles, "recipients-file", "")
	fs.Var(&identitiesList, "i", "")
	fs.Var(&identitiesList, "identity", "")
	fs.Var(&pluginList, "j", "")
	fs.Var(helpFlag{}, "help", "")
	fs.Var(helpFlag{}, "h", "")

	// With ExitOnError, fs.Parse will call os.Exit(2) on parse error (after printing error + usage).
	fs.Parse(os.Args[1:])

	if versionFlag {
		fmt.Println(versionStr())
		os.Exit(0)
	}

	// If no args at all, show usage and exit 1.
	if len(os.Args) == 1 {
		printUsage()
		os.Exit(1)
	}

	// Validate incompatible options.
	if encryptFlag && decryptFlag {
		errorf("-e/--encrypt can't be used with -d/--decrypt")
	}
	if passphraseFlag && decryptFlag {
		errorWithHint("note that password protected files are detected automatically", "-p/--passphrase can't be used with -d/--decrypt")
	}
	if armorFlag && decryptFlag {
		errorWithHint("note that armored files are detected automatically, try again without -a/--armor", "-a/--armor can't be used with -d/--decrypt")
	}
	if len(recipientsList) > 0 && decryptFlag {
		errorWithHint("did you mean to use -i/--identity to specify a private key?", "-r/--recipient can't be used with -d/--decrypt")
	}
	if len(recipientsFiles) > 0 && decryptFlag {
		errorWithHint("did you mean to use -i/--identity to specify a private key?", "-R/--recipients-file can't be used with -d/--decrypt")
	}
	if passphraseFlag && (len(recipientsList) > 0 || len(recipientsFiles) > 0) {
		errorf("-p/--passphrase can't be combined with -r/--recipient")
	}
	if passphraseFlag && (len(identitiesList) > 0 || len(pluginList) > 0) {
		errorf("-p/--passphrase can't be combined with -i/--identity and -j")
	}
	if len(pluginList) > 0 && !encryptFlag && !decryptFlag {
		// OK - allowed?
	}

	if !decryptFlag && !encryptFlag && !passphraseFlag && len(recipientsList) == 0 && len(recipientsFiles) == 0 && len(identitiesList) == 0 && len(pluginList) == 0 {
		// No input flags given at all (just positional args or nothing). Missing recipients.
		errorWithHint("did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?",
			"missing recipients")
	}

	args := fs.Args()
	if len(args) > 1 {
		var parts []string
		for _, a := range args {
			parts = append(parts, fmt.Sprintf("%q", a))
		}
		errorWithHint("only a single input file may be specified at a time", "too many INPUT arguments: "+strings.Join(parts, " "))
	}
	var inputPath string
	if len(args) == 1 {
		inputPath = args[0]
	}

	// Default to encrypt mode unless -d is given.
	if decryptFlag {
		runDecrypt(inputPath, outputPath, identitiesList)
	} else {
		if !encryptFlag && !passphraseFlag && len(recipientsList) == 0 && len(recipientsFiles) == 0 {
			errorWithHint("did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?",
				"missing recipients")
		}
		runEncrypt(inputPath, outputPath, armorFlag, passphraseFlag, recipientsList, recipientsFiles, identitiesList, encryptFlag)
	}
}

// ----- encrypt -----

func runEncrypt(inputPath, outputPath string, armorOut, passphrase bool, rFlags, RFlags, iFlags multiString, explicitEncrypt bool) {
	if passphrase {
		if len(rFlags) > 0 {
			errorf("-p/--passphrase can't be combined with -r/--recipient")
		}
		if len(RFlags) > 0 {
			errorf("-p/--passphrase can't be combined with -R/--recipients-file")
		}
	}
	if len(iFlags) > 0 && !explicitEncrypt {
		// identity-based encryption requires explicit -e
		errorf("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt")
	}

	input, inputIsStdin, cleanup, err := openInput(inputPath)
	if err != nil {
		errorf("%s", err.Error())
	}
	defer cleanup()

	var recipients []age.Recipient
	for _, s := range rFlags {
		r, err := parseRecipient(s)
		if err != nil {
			errorf("%s", err.Error())
		}
		recipients = append(recipients, r)
	}
	for _, path := range RFlags {
		rs, err := parseRecipientsFile(path, inputIsStdin)
		if err != nil {
			errorf("%s", err.Error())
		}
		recipients = append(recipients, rs...)
	}
	if passphrase {
		pass, err := getPassphraseForEncrypt()
		if err != nil {
			errorf("%s", err.Error())
		}
		recipients = append(recipients, age.NewScryptRecipient(pass))
	}
	// -i identities used for encryption (symmetric)
	for _, p := range iFlags {
		ids, err := parseIdentitiesFile(p, inputIsStdin)
		if err != nil {
			errorf("%s", err.Error())
		}
		for _, id := range ids {
			if r := identityToRecipient(id); r != nil {
				recipients = append(recipients, r)
			}
		}
	}

	if len(recipients) == 0 {
		errorWithHint("did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?",
			"missing recipients")
	}

	// Deduplicate recipients by string form (for X25519-like).
	recipients = dedupRecipients(recipients)

	output, cleanupO, err := openOutput(outputPath)
	if err != nil {
		errorf("%s", err.Error())
	}

	var w io.Writer = output
	var armorCloser io.Closer
	if armorOut {
		aw := armor.NewWriter(output)
		w = aw
		armorCloser = aw
	}

	encW, err := age.Encrypt(w, recipients...)
	if err != nil {
		errorf("%s", err.Error())
	}

	if _, err := io.Copy(encW, input); err != nil {
		errorf("%s", err.Error())
	}
	if err := encW.Close(); err != nil {
		errorf("%s", err.Error())
	}
	if armorCloser != nil {
		if err := armorCloser.Close(); err != nil {
			errorf("%s", err.Error())
		}
	}
	cleanupO()
}

// ----- decrypt -----

func runDecrypt(inputPath, outputPath string, iFlags multiString) {
	input, inputIsStdin, cleanup, err := openInput(inputPath)
	if err != nil {
		errorf("%s", err.Error())
	}
	defer cleanup()

	// Wrap with armor reader (transparently detects).
	aReader := armor.NewReader(input)

	// Try to read the header to detect scrypt/passphrase files.
	// We'll peek by using a bufio reader chain, but simpler: use io.TeeReader trick.
	// Actually let's just read all data... no, that won't work for large files.
	// Instead, we need age.Decrypt to handle identity selection.

	// If identities provided, parse them all first.
	var identities []age.Identity
	var haveIdentities bool
	for _, p := range iFlags {
		ids, err := parseIdentitiesFile(p, inputIsStdin)
		if err != nil {
			errorf("%s", err.Error())
		}
		identities = append(identities, ids...)
		haveIdentities = true
	}

	// For passphrase detection, we need to peek the file. Peek the header.
	br := bufio.NewReader(aReader)
	// Peek enough bytes to see "-> scrypt".
	peeked, _ := br.Peek(256)
	header := string(peeked)
	// Check for "-> scrypt" in header
	if strings.Contains(header, "-> scrypt ") {
		if haveIdentities {
			errorf("file is passphrase-encrypted, but identities were provided")
		}
		pass, err := getPassphrase("Enter passphrase:")
		if err != nil {
			errorf("%s", err.Error())
		}
		identities = []age.Identity{age.NewScryptIdentity(pass)}
	} else if !haveIdentities {
		errorf("missing identities")
	}

	r, err := age.Decrypt(br, identities...)
	if err != nil {
		errorf("%s", err.Error())
	}

	output, cleanupO, err := openOutput(outputPath)
	if err != nil {
		errorf("%s", err.Error())
	}

	if _, err := io.Copy(output, r); err != nil {
		errorf("%s", err.Error())
	}
	cleanupO()
}

// ----- helpers -----

func parseRecipient(s string) (age.Recipient, error) {
	lower := strings.ToLower(s)
	if strings.HasPrefix(lower, "age1") {
		return age.ParseX25519Recipient(s)
	}
	if strings.HasPrefix(s, "ssh-rsa ") || strings.HasPrefix(s, "ssh-ed25519 ") || strings.HasPrefix(s, "sk-ssh-ed25519@openssh.com ") {
		return nil, fmt.Errorf("malformed SSH recipient: %q: ssh: no key found", s)
	}
	if strings.HasPrefix(s, "ssh-") {
		return nil, fmt.Errorf("malformed SSH recipient: %q: ssh: no key found", s)
	}
	return nil, fmt.Errorf("unknown recipient type: %q", s)
}

func parseRecipientsFile(path string, inputIsStdin bool) ([]age.Recipient, error) {
	var f io.Reader
	if path == "-" {
		if inputIsStdin {
			return nil, fmt.Errorf("failed to parse recipient file %q: standard input is used for multiple purposes", path)
		}
		f = os.Stdin
	} else {
		file, err := os.Open(path)
		if err != nil {
			return nil, fmt.Errorf("failed to parse recipient file %q: failed to open recipient file: %w", path, err)
		}
		defer file.Close()
		f = file
	}
	scanner := bufio.NewScanner(f)
	var out []age.Recipient
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := strings.TrimRight(scanner.Text(), "\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		r, err := parseRecipient(line)
		if err != nil {
			return nil, fmt.Errorf("failed to parse recipient file %q: error at line %d: %s", path, lineNo, err.Error())
		}
		out = append(out, r)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("failed to parse recipient file %q: %w", path, err)
	}
	return out, nil
}

func parseIdentitiesFile(path string, inputIsStdin bool) ([]age.Identity, error) {
	var r io.Reader
	if path == "-" {
		if inputIsStdin {
			return nil, fmt.Errorf("reading %q: standard input is used for multiple purposes", path)
		}
		r = os.Stdin
	} else {
		f, err := os.Open(path)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to open file: %w", path, err)
		}
		defer f.Close()
		r = f
	}

	// Pre-read to detect passphrase-encrypted age file.
	br := bufio.NewReader(r)
	head, _ := br.Peek(256)
	if strings.HasPrefix(string(head), "age-encryption.org/v1\n") || strings.HasPrefix(string(head), "-----BEGIN AGE ENCRYPTED FILE") {
		// decrypt the file with scrypt identity
		arReader := armor.NewReader(br)
		pass, err := getPassphrase(fmt.Sprintf("Enter passphrase for identity file %q:", path))
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", path, err)
		}
		id := age.NewScryptIdentity(pass)
		dr, err := age.Decrypt(arReader, id)
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", path, err)
		}
		b, err := io.ReadAll(dr)
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", path, err)
		}
		ids, perr := parseIdentitiesBytes(b, path)
		if perr != nil {
			return nil, perr
		}
		return ids, nil
	}

	b, err := io.ReadAll(br)
	if err != nil {
		return nil, fmt.Errorf("reading %q: %w", path, err)
	}
	return parseIdentitiesBytes(b, path)
}

func parseIdentitiesBytes(data []byte, path string) ([]age.Identity, error) {
	var out []age.Identity
	lines := strings.Split(string(data), "\n")
	lineNo := 0
	var hasAny bool
	for _, line := range lines {
		lineNo++
		line = strings.TrimRight(line, "\r")
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		hasAny = true
		upper := strings.ToUpper(trimmed)
		if strings.HasPrefix(upper, "AGE-SECRET-KEY-1") {
			id, err := age.ParseX25519Identity(trimmed)
			if err != nil {
				return nil, fmt.Errorf("reading %q: failed to read %q: error at line %d: %s", path, path, lineNo, err.Error())
			}
			out = append(out, id)
		} else {
			return nil, fmt.Errorf("reading %q: failed to read %q: error at line %d: unknown identity type", path, path, lineNo)
		}
	}
	if !hasAny {
		return nil, fmt.Errorf("reading %q: failed to read %q: no identities found", path, path)
	}
	return out, nil
}

func identityToRecipient(id age.Identity) age.Recipient {
	if x, ok := id.(*age.X25519Identity); ok {
		return x.Recipient()
	}
	return nil
}

func dedupRecipients(rs []age.Recipient) []age.Recipient {
	seen := map[string]bool{}
	var out []age.Recipient
	for _, r := range rs {
		key := fmt.Sprintf("%T:%v", r, r)
		if x, ok := r.(*age.X25519Recipient); ok {
			key = "X25519:" + x.String()
			if seen[key] {
				warningf("duplicate recipient %q", x.String())
				continue
			}
			seen[key] = true
		}
		out = append(out, r)
	}
	return out
}

func openInput(path string) (io.Reader, bool, func(), error) {
	if path == "" || path == "-" {
		return os.Stdin, true, func() {}, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, false, nil, fmt.Errorf("reading %q: failed to open file: %w", path, err)
	}
	return f, false, func() { f.Close() }, nil
}

func openOutput(path string) (io.Writer, func(), error) {
	if path == "" || path == "-" {
		return os.Stdout, func() {}, nil
	}
	f, err := os.Create(path)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to create output: %w", err)
	}
	return f, func() { f.Close() }, nil
}

// ----- passphrase prompts -----

func getPassphrase(prompt string) (string, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return "", fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	defer tty.Close()
	fmt.Fprint(tty, prompt+" ")
	// Read line without echo - requires stty or termios. Use a simple echo-on read (not ideal).
	reader := bufio.NewReader(tty)
	line, err := reader.ReadString('\n')
	if err != nil {
		return "", fmt.Errorf("could not read passphrase: %w", err)
	}
	return strings.TrimRight(line, "\r\n"), nil
}

func getPassphraseForEncrypt() (string, error) {
	pass, err := getPassphrase("Enter passphrase (leave empty to autogenerate a secure one):")
	if err != nil {
		return "", err
	}
	if pass == "" {
		// Autogenerate a passphrase.
		pass = generatePassphrase()
		fmt.Fprintf(os.Stderr, "Using the autogenerated passphrase %q.\n", pass)
	} else {
		conf, err := getPassphrase("Confirm passphrase:")
		if err != nil {
			return "", err
		}
		if conf != pass {
			return "", errors.New("passphrases didn't match")
		}
	}
	return pass, nil
}

// generatePassphrase generates a 10-word passphrase from a small wordlist.
func generatePassphrase() string {
	// Simple placeholder: pick 10 words deterministic from wordlist using rand.
	// For compatibility with age, the wordlist should match BIP39 English, but we'll use a built-in list.
	words := passphraseWords
	var sb strings.Builder
	buf := make([]byte, 10*2)
	if _, err := randomRead(buf); err != nil {
		panic(err)
	}
	for i := 0; i < 10; i++ {
		idx := (int(buf[i*2])<<8 | int(buf[i*2+1])) % len(words)
		if i > 0 {
			sb.WriteByte('-')
		}
		sb.WriteString(words[idx])
	}
	return sb.String()
}

func randomRead(b []byte) (int, error) {
	f, err := os.Open("/dev/urandom")
	if err != nil {
		return 0, err
	}
	defer f.Close()
	return io.ReadFull(f, b)
}
